            tagline = "A school club discovers that a seed collection is really a record of community knowledge.",
            parts = listOf(
                StoryPart(1, "The Tin on the Shelf", listOf("Mira found a tin of seed packets while helping organise the school library's nature shelf. Each packet carried a handwritten name and a date.", "The librarian said the tin had been donated years earlier, but its catalogue entry was missing.", "Mira asked the gardening club to help identify the collection.")),
                StoryPart(2, "Names in the Margins", listOf("The packets contained notes about planting seasons, soil, and family gardens. Some names were unfamiliar; others matched streets nearby.", "The club decided not to plant anything until they knew what the seeds were and whether they were still suitable.", "They photographed the labels and asked a local horticulture group for guidance.")),
                StoryPart(3, "The Donor's Note", listOf("A folded note named Mrs Akin as the collector and said the packets represented plants grown by neighbours.", "The school office found an old contact card for her family. Her grandson, Femi, agreed to visit and explain what he knew.", "He brought a notebook that had belonged to his grandmother.")),
                StoryPart(4, "A Garden in the Notebook", listOf("The notebook mapped a shared garden where neighbours exchanged seeds and advice. Each entry named the person who contributed a variety and described its growing conditions.", "The garden had closed when the land was redeveloped, but many contributors still lived in the area.", "Mira suggested creating an oral history project alongside the seed catalogue.")),
                StoryPart(5, "Checking the Collection", listOf("A horticulture volunteer reviewed the packets and identified which could be safely documented. Some were too old or uncertain to use for planting.", "The club marked those packets as historical samples and kept them sealed. The volunteer explained how to source verified seeds for a new garden.", "The students learned that preserving a collection did not mean using every item.")),
                StoryPart(6, "The Contributors", listOf("Femi helped contact former gardeners. Several people brought photographs and corrected spellings in the notebook.", "One contributor explained that the garden had shared food during difficult seasons and taught children how to care for plants.", "The club recorded each story only after the speaker approved the notes.")),
                StoryPart(7, "A New Plot", listOf("The school approved a small plot for a teaching garden. The horticulture volunteer recommended suitable, locally available seeds.", "Students planned accessible paths, clear labels, and a rota that included watering during holidays.", "The old collection remained an archive, while the new garden used verified supplies.")),
                StoryPart(8, "The First Harvest Plan", listOf("The club created a calendar showing when to plant, observe, and review each crop. They included a space for recording unexpected results.", "Former gardeners offered advice but encouraged students to make their own observations.", "Mira added a note that advice should be tested against the conditions in the new plot.")),
                StoryPart(9, "A Growing Exhibition", listOf("The library displayed the seed packets, notebook copies, and approved community stories beside photographs of the new garden.", "Visitors learned how seed saving, careful identification, and shared records supported local knowledge.", "Femi donated a photograph of his grandmother teaching children to label jars.")),
                StoryPart(10, "A Collection with a Future", listOf("The garden produced its first small harvest, which the club shared according to the school's agreed rules.", "The seed archive was catalogued and stored safely, and the library created a digital record for future students.", "Mira added a final entry: the collection was not just about seeds. It held the names, experiments, generosity, and patient knowledge of people who had grown things together."))
